code.source:
#include <iostream>
using namespace std;

struct Noisy {
    Noisy() { cout << "open" << endl; }
    ~Noisy() { cout << "close" << endl; }
};

int main() {
    {
        Noisy n;
        cout << "working" << endl;
    }
    cout << "after the block" << endl;
    return 0;
}

#include <iostream>
using namespace std;

struct Noisy {
    Noisy() { cout << "open" << endl; }
    ~Noisy() { cout << "close" << endl; }
};

void work(bool fail) {
    Noisy* n = new Noisy;
    if (fail) {
        return;
    }
    delete n;
}

int main() {
    work(false);
    work(true);
    return 0;
}

